insert into public."content_drafts" ("id", "academy_id", "grade", "subject_id", "title", "objective", "unit_title", "standards_tags", "essential_question", "student_summary", "why_it_matters", "vocabulary_terms", "prerequisite_skills", "lesson_sections", "helper_notes", "common_misunderstandings", "visual_supports", "quiz_questions", "source_cards", "group_homework", "status", "blocked_reason", "review_notes", "accessibility_notes", "age_fit_notes", "lesson_body_ready", "teaching_completeness_status", "teaching_completeness_issues", "source_lesson_id", "source_tool_call_id", "redesign_task_ids", "research_source_ids", "truth_score", "truth_issues", "needs_external_research", "truth_review_status", "latest_review", "review_history", "review_version", "created_at", "updated_at")
values ('draft-pilot-g3-fractions-number-line', 'foundation', '3', 'math', 'Fractions on a Number Line', 'Place unit fractions and equivalent fractions on a number line.', 'Fractions', '["ccss-math"]'::jsonb, 'How can a number line show that a fraction is a number and not just a piece of a shape?', 'Fractions on a number line are about equal spaces between 0 and 1, not just marks on the line.', 'This matters because learners use fractions to explain, build, predict, compare, or solve beyond one quiz.', '["model","strategy","evidence"]'::jsonb, '["Say what you already know about this math idea.","Point to one example or clue before answering.","Explain the first step in your own words."]'::jsonb, '{"warmUp":"Compare halves, thirds, and fourths using equal-size visual parts.","directInstruction":"Fractions show equal parts of a whole. On a number line, the denominator tells how many equal spaces fit between 0 and 1.","guidedPractice":"Drag 1/2, 1/3, and 3/4 to the correct tick marks.","interactiveActivity":"Build a paper strip number line and mark equal jumps.","independentPractice":"Solve 10 placement problems with unit fractions and equivalent fractions.","reteachPath":"Use fraction strips first, then transfer the same spacing to the number line.","challengePath":"Explain why 2/4 and 1/2 land on the same point."}'::jsonb, '[{"title":"Look","note":"Use tape on the floor or paper strips before asking for a written answer."},{"title":"Build","note":"Ask the learner to point to the whole, then the equal spaces, then the target fraction."},{"title":"Explain","note":"Have the child say: I counted spaces, not tick marks."}]'::jsonb, '[{"misunderstanding":"Counting tick marks instead of spaces.","repair":"Cover the tick marks and ask the learner to hop only the spaces between 0 and 1.","signal":""},{"misunderstanding":"Thinking fourths are always bigger than halves because 4 is bigger than 2.","repair":"Compare same-size strips and show that more pieces means smaller pieces.","signal":""}]'::jsonb, '[{"placement":"lesson-hero","title":"Fraction path image","description":"A number line from 0 to 1 with equal jumps for halves, thirds, and fourths.","prompt":"Create a bold educational hero image for Fractions on a Number Line. Show the concept clearly with no real children, no logos, and no copyrighted characters.","altText":"A number line from 0 to 1 with equal jumps for halves, thirds, and fourths."},{"placement":"teaching-diagram","title":"Fractions on a Number Line diagram","description":"Whole interval: Mark 0 and 1 first so the child sees the whole before naming the parts. Equal spaces: Count the spaces between tick marks; the denominator names the number of equal spaces. Same point: Use 1/2 and 2/4 on the same line to show equivalent fractions visually.","prompt":"Create a labeled diagram for Fractions on a Number Line with 3-5 readable callouts and high contrast.","altText":"Diagram showing Whole interval, Equal spaces, Same point."},{"placement":"ai-tutor","title":"Fractions on a Number Line tutor help card","description":"Write which part is confusing: finding the whole, making equal spaces, or placing the fraction.","prompt":"Create a small tutor help card for Fractions on a Number Line that shows one visual hint and one retry step.","altText":"Tutor visual hint for Fractions on a Number Line."}]'::jsonb, '[{"questionText":"Where does 1/2 belong on a number line from 0 to 1?","questionType":"multiple-choice","choices":["At the middle point","At 0","At the first of three spaces","Past 1"],"correctAnswer":"At the middle point","explanation":"One half divides the space from 0 to 1 into two equal parts and lands in the middle.","difficultyLevel":"core","skillTag":"math-fractions","standardTag":"ccss-math"},{"questionText":"Which fraction is equivalent to 1/2?","questionType":"multiple-choice","choices":["1/3","2/4","3/3","4/2"],"correctAnswer":"2/4","explanation":"Two fourths covers the same amount as one half.","difficultyLevel":"core","skillTag":"math-fractions","standardTag":"ccss-math"}]'::jsonb, '[{"sourceId":"standard-ccss-math","title":"ccss-math standards tag","url":"","claim":"Fractions on a Number Line is aligned to ccss-math; state-specific mapping remains data-driven before district rollout.","checkedAt":"2026-07-10T12:00:00.000Z","reviewerNote":"Internal standards tag reviewed for the pilot publication bundle."}]'::jsonb, '{}'::jsonb, 'published', '', 'Published core pilot lesson reviewed for student-facing app-led instruction, visual support, tutor prompts, and mastery checks.', 'Includes alt text, short chunks, keyboard-friendly tasks, high-contrast SVG support, and non-color-only instructions.', 'foundation lesson uses age-fit pacing, vocabulary, visuals, active learning, and retry supports.', true, 'ready', '[]'::jsonb, 'g3-fractions-number-line', '', '[]'::jsonb, '[]'::jsonb, 5, '[]'::jsonb, false, 'approved', '{}'::jsonb, '[]'::jsonb, 0, '2026-07-10T12:00:00.000Z', '2026-07-10T12:00:00.000Z')
