insert into public."content_drafts" ("id", "academy_id", "grade", "subject_id", "title", "objective", "unit_title", "standards_tags", "essential_question", "student_summary", "why_it_matters", "vocabulary_terms", "prerequisite_skills", "lesson_sections", "helper_notes", "common_misunderstandings", "visual_supports", "quiz_questions", "source_cards", "group_homework", "status", "blocked_reason", "review_notes", "accessibility_notes", "age_fit_notes", "lesson_body_ready", "teaching_completeness_status", "teaching_completeness_issues", "source_lesson_id", "source_tool_call_id", "redesign_task_ids", "research_source_ids", "truth_score", "truth_issues", "needs_external_research", "truth_review_status", "latest_review", "review_history", "review_version", "created_at", "updated_at")
values ('draft-pilot-g3-ela-main-idea-evidence', 'foundation', '3', 'ela', 'Main Idea Detective', 'Identify the main idea of a nonfiction passage and support it with two details.', 'Main Idea', '["ccss-ela"]'::jsonb, 'How can evidence help us identify the big idea?', 'A main idea is the big point that the strongest details all help prove.', 'This matters because learners use main idea to explain, build, predict, compare, or solve beyond one quiz.', '["main idea","detail","evidence"]'::jsonb, '["Say what you already know about this ela idea.","Point to one example or clue before answering.","Explain the first step in your own words."]'::jsonb, '{"warmUp":"Look at four picture clues and guess what they all have in common.","directInstruction":"The main idea is what a text is mostly about. Strong details prove the main idea instead of adding random facts.","guidedPractice":"Read a short paragraph and drag two details onto the evidence board.","interactiveActivity":"Create a detective board with one main idea and two evidence cards.","independentPractice":"Choose the best main idea and explain why two details support it.","reteachPath":"Ask what all the details have in common before choosing a main idea.","challengePath":"Find one detail that is interesting but does not support the main idea."}'::jsonb, '[{"title":"Look","note":"Ask: What do most of these details have in common?"},{"title":"Build","note":"Use two proof cards before writing the final sentence."},{"title":"Explain","note":"Have the learner explain why one detail does not belong."}]'::jsonb, '[{"misunderstanding":"Choosing the first sentence as the main idea every time.","repair":"Check whether every detail supports it before accepting it.","signal":""},{"misunderstanding":"Picking an interesting detail instead of the big point.","repair":"Ask whether the detail is one clue or the whole message.","signal":""}]'::jsonb, '[{"placement":"lesson-hero","title":"Evidence detective board","description":"A visual board with a main idea clue in the center and detail cards connected around it.","prompt":"Create a bold educational hero image for Main Idea Detective. Show the concept clearly with no real children, no logos, and no copyrighted characters.","altText":"A visual board with a main idea clue in the center and detail cards connected around it."},{"placement":"teaching-diagram","title":"Main Idea Detective diagram","description":"Main idea: Put the big point in the center only after checking several details. Proof details: Details should connect back to the center idea, not just sound interesting. Distractor detail: A fun fact can be true and still not prove the main idea.","prompt":"Create a labeled diagram for Main Idea Detective with 3-5 readable callouts and high contrast.","altText":"Diagram showing Main idea, Proof details, Distractor detail."},{"placement":"ai-tutor","title":"Main Idea Detective tutor help card","description":"Write whether you are stuck finding the big idea, choosing proof details, or rejecting distractors.","prompt":"Create a small tutor help card for Main Idea Detective that shows one visual hint and one retry step.","altText":"Tutor visual hint for Main Idea Detective."}]'::jsonb, '[{"questionText":"What is the main idea of a paragraph?","questionType":"multiple-choice","choices":["What the text is mostly about","The longest word","The first name in the text","A random fun fact"],"correctAnswer":"What the text is mostly about","explanation":"The main idea tells what the whole paragraph is mostly about.","difficultyLevel":"core","skillTag":"ela-main-idea","standardTag":"ccss-ela"},{"questionText":"Which detail best supports a passage about how bees help plants?","questionType":"multiple-choice","choices":["Bees move pollen between flowers","Some people wear yellow shirts","A flower can be drawn with crayons","Honey jars can be heavy"],"correctAnswer":"Bees move pollen between flowers","explanation":"Moving pollen explains how bees help plants.","difficultyLevel":"core","skillTag":"ela-main-idea","standardTag":"ccss-ela"}]'::jsonb, '[{"sourceId":"standard-ccss-ela","title":"ccss-ela standards tag","url":"","claim":"Main Idea Detective is aligned to ccss-ela; state-specific mapping remains data-driven before district rollout.","checkedAt":"2026-07-10T12:00:00.000Z","reviewerNote":"Internal standards tag reviewed for the pilot publication bundle."}]'::jsonb, '{}'::jsonb, 'published', '', 'Published core pilot lesson reviewed for student-facing app-led instruction, visual support, tutor prompts, and mastery checks.', 'Includes alt text, short chunks, keyboard-friendly tasks, high-contrast SVG support, and non-color-only instructions.', 'foundation lesson uses age-fit pacing, vocabulary, visuals, active learning, and retry supports.', true, 'ready', '[]'::jsonb, 'g3-ela-main-idea-evidence', '', '[]'::jsonb, '[]'::jsonb, 5, '[]'::jsonb, false, 'approved', '{}'::jsonb, '[]'::jsonb, 0, '2026-07-10T12:00:00.000Z', '2026-07-10T12:00:00.000Z')
