insert into public."content_drafts" ("id", "academy_id", "grade", "subject_id", "title", "objective", "unit_title", "standards_tags", "essential_question", "student_summary", "why_it_matters", "vocabulary_terms", "prerequisite_skills", "lesson_sections", "helper_notes", "common_misunderstandings", "visual_supports", "quiz_questions", "source_cards", "group_homework", "status", "blocked_reason", "review_notes", "accessibility_notes", "age_fit_notes", "lesson_body_ready", "teaching_completeness_status", "teaching_completeness_issues", "source_lesson_id", "source_tool_call_id", "redesign_task_ids", "research_source_ids", "truth_score", "truth_issues", "needs_external_research", "truth_review_status", "latest_review", "review_history", "review_version", "created_at", "updated_at")
values ('draft-pilot-g3-science-mini-ecosystem', 'foundation', '3', 'science', 'Build a Mini Ecosystem', 'Explain how organisms depend on each other in a small ecosystem.', 'Ecosystems', '["ngss"]'::jsonb, 'How can a model help us explain what changes in a living system?', 'An ecosystem is a set of living and nonliving parts that depend on each other.', 'This matters because learners use ecosystems to explain, build, predict, compare, or solve beyond one quiz.', '["system","observation","explanation"]'::jsonb, '["Say what you already know about this science idea.","Point to one example or clue before answering.","Explain the first step in your own words."]'::jsonb, '{"warmUp":"Name three living or nonliving parts of a backyard or park.","directInstruction":"Organisms depend on food, water, shelter, sunlight, and other organisms. A model can show these connections.","guidedPractice":"Connect plants, insects, water, soil, and sunlight with dependency arrows.","interactiveActivity":"Build a mini ecosystem model with labeled arrows.","independentPractice":"Explain what might happen if one part of the ecosystem disappears.","reteachPath":"Separate living and nonliving parts, then ask what each part needs.","challengePath":"Compare a pond ecosystem and a garden ecosystem."}'::jsonb, '[{"title":"Look","note":"Sort cards into living and nonliving before drawing arrows."},{"title":"Build","note":"Ask what each part needs to survive."},{"title":"Explain","note":"Use a missing-part challenge to test whether the learner understands relationships."}]'::jsonb, '[{"misunderstanding":"Thinking only animals are important in an ecosystem.","repair":"Trace how plants, sunlight, water, and soil support the animals.","signal":""},{"misunderstanding":"Drawing arrows as decoration instead of relationships.","repair":"Require every arrow to be read aloud as depends on or gives to.","signal":""}]'::jsonb, '[{"placement":"lesson-hero","title":"Mini ecosystem image","description":"A model showing sun, plants, insects, soil, water, and a simple food connection.","prompt":"Create a bold educational hero image for Build a Mini Ecosystem. Show the concept clearly with no real children, no logos, and no copyrighted characters.","altText":"A model showing sun, plants, insects, soil, water, and a simple food connection."},{"placement":"teaching-diagram","title":"Build a Mini Ecosystem diagram","description":"Energy source: Sunlight starts many food connections because plants use it to make food. Dependency arrow: An arrow means one part needs or affects another part. System change: Removing water, plants, or insects changes more than one part of the ecosystem.","prompt":"Create a labeled diagram for Build a Mini Ecosystem with 3-5 readable callouts and high contrast.","altText":"Diagram showing Energy source, Dependency arrow, System change."},{"placement":"ai-tutor","title":"Build a Mini Ecosystem tutor help card","description":"Write whether you are stuck on living parts, nonliving parts, arrows, or what changes when one part disappears.","prompt":"Create a small tutor help card for Build a Mini Ecosystem that shows one visual hint and one retry step.","altText":"Tutor visual hint for Build a Mini Ecosystem."}]'::jsonb, '[{"questionText":"Why do many plants need sunlight?","questionType":"multiple-choice","choices":["To make food","To learn spelling","To become rocks","To stop all insects"],"correctAnswer":"To make food","explanation":"Plants use sunlight as part of making their food.","difficultyLevel":"core","skillTag":"science-ecosystems","standardTag":"ngss"},{"questionText":"What does a dependency arrow show in an ecosystem model?","questionType":"multiple-choice","choices":["How one part depends on another","Which word is longest","Where to write your name","How to erase the model"],"correctAnswer":"How one part depends on another","explanation":"Dependency arrows show relationships between parts of a system.","difficultyLevel":"core","skillTag":"science-ecosystems","standardTag":"ngss"}]'::jsonb, '[{"sourceId":"standard-ngss","title":"ngss standards tag","url":"","claim":"Build a Mini Ecosystem is aligned to ngss; state-specific mapping remains data-driven before district rollout.","checkedAt":"2026-07-10T12:00:00.000Z","reviewerNote":"Internal standards tag reviewed for the pilot publication bundle."}]'::jsonb, '{}'::jsonb, 'published', '', 'Published core pilot lesson reviewed for student-facing app-led instruction, visual support, tutor prompts, and mastery checks.', 'Includes alt text, short chunks, keyboard-friendly tasks, high-contrast SVG support, and non-color-only instructions.', 'foundation lesson uses age-fit pacing, vocabulary, visuals, active learning, and retry supports.', true, 'ready', '[]'::jsonb, 'g3-science-mini-ecosystem', '', '[]'::jsonb, '[]'::jsonb, 5, '[]'::jsonb, false, 'approved', '{}'::jsonb, '[]'::jsonb, 0, '2026-07-10T12:00:00.000Z', '2026-07-10T12:00:00.000Z')
