insert into public."content_drafts" ("id", "academy_id", "grade", "subject_id", "title", "objective", "unit_title", "standards_tags", "essential_question", "student_summary", "why_it_matters", "vocabulary_terms", "prerequisite_skills", "lesson_sections", "helper_notes", "common_misunderstandings", "visual_supports", "quiz_questions", "source_cards", "group_homework", "status", "blocked_reason", "review_notes", "accessibility_notes", "age_fit_notes", "lesson_body_ready", "teaching_completeness_status", "teaching_completeness_issues", "source_lesson_id", "source_tool_call_id", "redesign_task_ids", "research_source_ids", "truth_score", "truth_issues", "needs_external_research", "truth_review_status", "latest_review", "review_history", "review_version", "created_at", "updated_at")
values ('draft-pilot-g6-math-ratios-unit-rates', 'bridge', '6', 'math', 'Ratio Quest: Build a Better Deal', 'Use equivalent ratios, ratio tables, double number lines, and unit rates to compare real-world deals.', 'Ratios, Rates, and Proportional Reasoning', '["ccss-math"]'::jsonb, 'How can ratios help us compare different-size deals fairly?', 'Ratios compare quantities, and unit rates make different-size deals fair to compare.', 'This matters because learners use ratios, rates, and proportional reasoning to explain, build, predict, compare, or solve beyond one quiz.', '["model","strategy","evidence"]'::jsonb, '["Say what you already know about this math idea.","Point to one example or clue before answering.","Explain the first step in your own words."]'::jsonb, '{"warmUp":"Look at two snack deals and vote for the better buy before calculating.","directInstruction":"A ratio compares two quantities. Equivalent ratios multiply both quantities by the same factor. A unit rate tells the amount for one, so deals can be compared fairly.","guidedPractice":"Complete a ratio table, then map the same values onto a double number line before writing the unit rate.","interactiveActivity":"Use the interactive ratio board to scale a recipe, ticket bundle, or snack-pack deal and defend the best choice.","independentPractice":"Compare two real-world deals and choose the better one using a labeled unit-rate sentence.","reteachPath":"Return to one ratio pair, label each quantity, and build only two equivalent rows before finding the unit rate.","challengePath":"Design a new deal that looks cheaper but is not better, then explain the trap."}'::jsonb, '[{"title":"Look","note":"Ask the learner to say what each number means before calculating."},{"title":"Build","note":"Use the double number line before the shortcut so the relationship stays visible."},{"title":"Explain","note":"Require a fairness sentence: I chose ___ because each one costs ___ or gives ___."}]'::jsonb, '[{"misunderstanding":"Adding the same number to both quantities and calling it equivalent.","repair":"Use a scale factor and ask whether both quantities were multiplied by the same number.","signal":""},{"misunderstanding":"Choosing the lower total price instead of the better unit rate.","repair":"Compare the cost for one item or one unit before deciding which deal is better.","signal":""},{"misunderstanding":"Reversing the ratio order.","repair":"Label the quantities first and keep the same order in the table, line, and sentence.","signal":""}]'::jsonb, '[{"placement":"lesson-hero","title":"Ratio table and double number line","description":"A neon market board comparing two snack packs with ratio tables, double number lines, and unit price callouts.","prompt":"Create a bold educational hero image for Ratio Quest: Build a Better Deal. Show the concept clearly with no real children, no logos, and no copyrighted characters.","altText":"Two snack deals are shown with matching ratio tables and double number lines. Labels point to equivalent ratios, scale factors, and unit rate."},{"placement":"teaching-diagram","title":"Ratio Quest: Build a Better Deal diagram","description":"Ratio pair: A ratio compares two quantities in a specific order, such as dollars to tickets or cups to scoops. Scale factor: Equivalent ratios keep the relationship the same by multiplying both quantities by the same factor. Unit rate: A unit rate tells the amount for one, which makes different-size deals easier to compare.","prompt":"Create a labeled diagram for Ratio Quest: Build a Better Deal with 3-5 readable callouts and high contrast.","altText":"Diagram showing Ratio pair, Scale factor, Unit rate."},{"placement":"ai-tutor","title":"Ratio Quest: Build a Better Deal tutor help card","description":"Write whether you are stuck on what the ratio means, how to scale it, how to use the double number line, or how to find the unit rate.","prompt":"Create a small tutor help card for Ratio Quest: Build a Better Deal that shows one visual hint and one retry step.","altText":"Tutor visual hint for Ratio Quest: Build a Better Deal."}]'::jsonb, '[{"questionText":"A pack has 6 pencils for $3. What is the cost per pencil?","questionType":"multiple-choice","choices":["$0.50 per pencil","$2 per pencil","$3 per pencil","$9 per pencil"],"correctAnswer":"$0.50 per pencil","explanation":"Divide $3 by 6 pencils. Each pencil costs $0.50.","difficultyLevel":"core","skillTag":"math-ratios-rates-and-proportional-reasoning","standardTag":"ccss-math"},{"questionText":"Which ratio is equivalent to 2 cups of juice for 5 cups of water?","questionType":"multiple-choice","choices":["4 cups of juice for 10 cups of water","3 cups of juice for 6 cups of water","2 cups of juice for 7 cups of water","5 cups of juice for 2 cups of water"],"correctAnswer":"4 cups of juice for 10 cups of water","explanation":"Multiplying both 2 and 5 by 2 gives 4 to 10, so the relationship stays the same.","difficultyLevel":"core","skillTag":"math-ratios-rates-and-proportional-reasoning","standardTag":"ccss-math"},{"questionText":"Deal A is 4 tickets for $12. Deal B is 6 tickets for $15. Which is the better price per ticket?","questionType":"multiple-choice","choices":["Deal B","Deal A","They are the same","There is not enough information"],"correctAnswer":"Deal B","explanation":"Deal A is $3 per ticket. Deal B is $2.50 per ticket, so Deal B is the better price.","difficultyLevel":"core","skillTag":"math-ratios-rates-and-proportional-reasoning","standardTag":"ccss-math"}]'::jsonb, '[{"sourceId":"standard-ccss-math","title":"ccss-math standards tag","url":"","claim":"Ratio Quest: Build a Better Deal is aligned to ccss-math; state-specific mapping remains data-driven before district rollout.","checkedAt":"2026-07-10T12:00:00.000Z","reviewerNote":"Internal standards tag reviewed for the pilot publication bundle."}]'::jsonb, '{"title":"Better deal crew","roles":["Deal scout","Table builder","Number-line mapper","Skeptic","Presenter"],"sharedArtifact":"Submit a one-page deal comparison with a ratio table, double number line, unit rate, and final recommendation.","individualAccountability":"Each learner explains one part in their own words."}'::jsonb, 'published', '', 'Published core pilot lesson reviewed for student-facing app-led instruction, visual support, tutor prompts, and mastery checks.', 'Includes alt text, short chunks, keyboard-friendly tasks, high-contrast SVG support, and non-color-only instructions.', 'bridge lesson uses age-fit pacing, vocabulary, visuals, active learning, and retry supports.', true, 'ready', '[]'::jsonb, 'g6-math-ratios-unit-rates', '', '[]'::jsonb, '[]'::jsonb, 5, '[]'::jsonb, false, 'approved', '{}'::jsonb, '[]'::jsonb, 0, '2026-07-10T12:00:00.000Z', '2026-07-10T12:00:00.000Z')
