insert into public."content_drafts" ("id", "academy_id", "grade", "subject_id", "title", "objective", "unit_title", "standards_tags", "essential_question", "student_summary", "why_it_matters", "vocabulary_terms", "prerequisite_skills", "lesson_sections", "helper_notes", "common_misunderstandings", "visual_supports", "quiz_questions", "source_cards", "group_homework", "status", "blocked_reason", "review_notes", "accessibility_notes", "age_fit_notes", "lesson_body_ready", "teaching_completeness_status", "teaching_completeness_issues", "source_lesson_id", "source_tool_call_id", "redesign_task_ids", "research_source_ids", "truth_score", "truth_issues", "needs_external_research", "truth_review_status", "latest_review", "review_history", "review_version", "created_at", "updated_at")
values ('draft-pilot-g6-earth-systems-weather', 'bridge', '6', 'science', 'Reading Weather Patterns', 'Use weather data to describe patterns and predict short-term changes.', 'Weather and Climate', '["ngss"]'::jsonb, 'How can weather data support a forecast without turning the forecast into a guess?', 'Weather predictions are evidence claims built from patterns in pressure, temperature, wind, and clouds.', 'This matters because learners use weather and climate to explain, build, predict, compare, or solve beyond one quiz.', '["system","observation","explanation"]'::jsonb, '["Say what you already know about this science idea.","Point to one example or clue before answering.","Explain the first step in your own words."]'::jsonb, '{"warmUp":"Look at a three-day temperature and cloud-cover chart.","directInstruction":"Weather patterns form when air pressure, temperature, humidity, and wind interact.","guidedPractice":"Match symbols on a weather map to observations.","interactiveActivity":"Build a weather station log for one week.","independentPractice":"Use a data table to write a two-sentence forecast.","reteachPath":"Review one variable at a time before combining the full forecast.","challengePath":"Compare forecast confidence when one data point is missing."}'::jsonb, '[{"title":"Look","note":"Ask students to separate observation, pattern, and prediction."},{"title":"Build","note":"Require a confidence rating so teams notice missing or weak evidence."},{"title":"Explain","note":"After real weather happens, revise the rule instead of only marking right or wrong."}]'::jsonb, '[{"misunderstanding":"Using one symbol as a complete forecast.","repair":"Ask for two data points before accepting the claim.","signal":""},{"misunderstanding":"Thinking a wrong forecast means the method failed.","repair":"Compare prediction to actuals and improve the rule using new evidence.","signal":""}]'::jsonb, '[{"placement":"lesson-hero","title":"Weather systems image","description":"A map-style weather visual with pressure zones, wind arrows, clouds, and temperature bands.","prompt":"Create a bold educational hero image for Reading Weather Patterns. Show the concept clearly with no real children, no logos, and no copyrighted characters.","altText":"A map-style weather visual with pressure zones, wind arrows, clouds, and temperature bands."},{"placement":"teaching-diagram","title":"Reading Weather Patterns diagram","description":"Pressure zone: High and low pressure help explain likely air movement and changing conditions. Wind arrow: Wind direction helps predict what kind of air may arrive next. Evidence claim: A forecast should cite at least two pieces of current map or table evidence.","prompt":"Create a labeled diagram for Reading Weather Patterns with 3-5 readable callouts and high contrast.","altText":"Diagram showing Pressure zone, Wind arrow, Evidence claim."},{"placement":"ai-tutor","title":"Reading Weather Patterns tutor help card","description":"Write whether you are stuck on pressure, wind arrows, data tables, or turning evidence into a forecast.","prompt":"Create a small tutor help card for Reading Weather Patterns that shows one visual hint and one retry step.","altText":"Tutor visual hint for Reading Weather Patterns."}]'::jsonb, '[{"questionText":"Which evidence best supports a short-term weather forecast?","questionType":"multiple-choice","choices":["A current pressure map","A list of favorite seasons","A drawing of clouds from last year","A map with no labels"],"correctAnswer":"A current pressure map","explanation":"Current pressure patterns are evidence scientists use to forecast weather.","difficultyLevel":"core","skillTag":"science-weather-and-climate","standardTag":"ngss"},{"questionText":"A falling air pressure reading often suggests what kind of change?","questionType":"multiple-choice","choices":["Possible stormy weather","No weather can happen","The season is over","All wind stops"],"correctAnswer":"Possible stormy weather","explanation":"Falling pressure can indicate approaching unsettled or stormy weather.","difficultyLevel":"core","skillTag":"science-weather-and-climate","standardTag":"ngss"}]'::jsonb, '[{"sourceId":"standard-ngss","title":"ngss standards tag","url":"","claim":"Reading Weather Patterns is aligned to ngss; state-specific mapping remains data-driven before district rollout.","checkedAt":"2026-07-10T12:00:00.000Z","reviewerNote":"Internal standards tag reviewed for the pilot publication bundle."}]'::jsonb, '{"title":"Family weather crew","roles":["Data lead","Map reader","Skeptic","Reporter","Reflection captain"],"sharedArtifact":"Submit a one-week weather board with predictions, actuals, and one improved forecast rule.","individualAccountability":"Each learner explains one part in their own words."}'::jsonb, 'published', '', 'Published core pilot lesson reviewed for student-facing app-led instruction, visual support, tutor prompts, and mastery checks.', 'Includes alt text, short chunks, keyboard-friendly tasks, high-contrast SVG support, and non-color-only instructions.', 'bridge lesson uses age-fit pacing, vocabulary, visuals, active learning, and retry supports.', true, 'ready', '[]'::jsonb, 'g6-earth-systems-weather', '', '[]'::jsonb, '[]'::jsonb, 5, '[]'::jsonb, false, 'approved', '{}'::jsonb, '[]'::jsonb, 0, '2026-07-10T12:00:00.000Z', '2026-07-10T12:00:00.000Z')
