insert into public."content_drafts" ("id", "academy_id", "grade", "subject_id", "title", "objective", "unit_title", "standards_tags", "essential_question", "student_summary", "why_it_matters", "vocabulary_terms", "prerequisite_skills", "lesson_sections", "helper_notes", "common_misunderstandings", "visual_supports", "quiz_questions", "source_cards", "group_homework", "status", "blocked_reason", "review_notes", "accessibility_notes", "age_fit_notes", "lesson_body_ready", "teaching_completeness_status", "teaching_completeness_issues", "source_lesson_id", "source_tool_call_id", "redesign_task_ids", "research_source_ids", "truth_score", "truth_issues", "needs_external_research", "truth_review_status", "latest_review", "review_history", "review_version", "created_at", "updated_at")
values ('draft-pilot-g9-biology-cells', 'scholar', '9', 'science', 'Cell Structure and Function', 'Explain how major cell structures support life processes.', 'Cells', '["ngss"]'::jsonb, 'How can structure-function evidence explain what a cell can and cannot do?', 'Cell structures are easier to remember when they are linked to jobs in a living system.', 'This matters because learners use cells to explain, build, predict, compare, or solve beyond one quiz.', '["system","observation","explanation"]'::jsonb, '["Say what you already know about this science idea.","Point to one example or clue before answering.","Explain the first step in your own words."]'::jsonb, '{"warmUp":"Compare a cell to a city system and name three jobs that must happen.","directInstruction":"Organelles perform specialized functions: the nucleus stores genetic instructions, mitochondria transfer energy, and membranes regulate movement.","guidedPractice":"Match organelles to evidence-based function statements.","interactiveActivity":"Build a labeled model with a claim-evidence-reasoning note.","independentPractice":"Analyze a cell diagram and explain what happens if one structure fails.","reteachPath":"Sort organelles by job category: information, energy, transport, structure.","challengePath":"Compare plant and animal cells using three structural differences."}'::jsonb, '[{"title":"Look","note":"Sort organelles by job category before memorizing names."},{"title":"Build","note":"Use claim-evidence-reasoning for every cell failure diagnosis."},{"title":"Explain","note":"Compare plant and animal cells by structure and function, not only appearance."}]'::jsonb, '[{"misunderstanding":"Memorizing organelle names without knowing the job.","repair":"Ask what would break in the cell if that structure stopped working.","signal":""},{"misunderstanding":"Confusing cell wall and cell membrane.","repair":"Compare support/protection with controlled movement across a boundary.","signal":""}]'::jsonb, '[{"placement":"lesson-hero","title":"Cell systems image","description":"A labeled cell diagram that connects structures to jobs: information, energy, transport, and protection.","prompt":"Create a bold educational hero image for Cell Structure and Function. Show the concept clearly with no real children, no logos, and no copyrighted characters.","altText":"A labeled cell diagram that connects structures to jobs: information, energy, transport, and protection."},{"placement":"teaching-diagram","title":"Cell Structure and Function diagram","description":"Information: The nucleus stores instructions that guide cell activity. Energy: Mitochondria transfer energy that cells can use for work. Boundary: The cell membrane controls movement into and out of the cell.","prompt":"Create a labeled diagram for Cell Structure and Function with 3-5 readable callouts and high contrast.","altText":"Diagram showing Information, Energy, Boundary."},{"placement":"ai-tutor","title":"Cell Structure and Function tutor help card","description":"Write whether you are stuck on organelle names, jobs, evidence, or comparing plant and animal cells.","prompt":"Create a small tutor help card for Cell Structure and Function that shows one visual hint and one retry step.","altText":"Tutor visual hint for Cell Structure and Function."}]'::jsonb, '[{"questionText":"Which structure controls what enters and leaves the cell?","questionType":"multiple-choice","choices":["Cell membrane","Nucleus","Ribosome","Vacuole"],"correctAnswer":"Cell membrane","explanation":"The cell membrane regulates movement into and out of the cell.","difficultyLevel":"core","skillTag":"science-cells","standardTag":"ngss"},{"questionText":"Which organelle is most directly tied to energy transfer?","questionType":"multiple-choice","choices":["Mitochondrion","Nucleus","Cell wall","Golgi body"],"correctAnswer":"Mitochondrion","explanation":"Mitochondria are the major site of cellular energy transfer.","difficultyLevel":"core","skillTag":"science-cells","standardTag":"ngss"}]'::jsonb, '[{"sourceId":"standard-ngss","title":"ngss standards tag","url":"","claim":"Cell Structure and Function is aligned to ngss; state-specific mapping remains data-driven before district rollout.","checkedAt":"2026-07-10T12:00:00.000Z","reviewerNote":"Internal standards tag reviewed for the pilot publication bundle."}]'::jsonb, '{"title":"Organelle emergency room","roles":["Systems doctor","Evidence analyst","Diagram designer","Skeptic","Presenter"],"sharedArtifact":"Diagnose a mystery cell failure and present the evidence trail.","individualAccountability":"Each learner defends one evidence choice and one next step."}'::jsonb, 'published', '', 'Published core pilot lesson reviewed for student-facing app-led instruction, visual support, tutor prompts, and mastery checks.', 'Includes alt text, short chunks, keyboard-friendly tasks, high-contrast SVG support, and non-color-only instructions.', 'scholar lesson uses age-fit pacing, vocabulary, visuals, active learning, and retry supports.', true, 'ready', '[]'::jsonb, 'g9-biology-cells', '', '[]'::jsonb, '[]'::jsonb, 5, '[]'::jsonb, false, 'approved', '{}'::jsonb, '[]'::jsonb, 0, '2026-07-10T12:00:00.000Z', '2026-07-10T12:00:00.000Z')
