insert into public."content_drafts" ("id", "academy_id", "grade", "subject_id", "title", "objective", "unit_title", "standards_tags", "essential_question", "student_summary", "why_it_matters", "vocabulary_terms", "prerequisite_skills", "lesson_sections", "helper_notes", "common_misunderstandings", "visual_supports", "quiz_questions", "source_cards", "group_homework", "status", "blocked_reason", "review_notes", "accessibility_notes", "age_fit_notes", "lesson_body_ready", "teaching_completeness_status", "teaching_completeness_issues", "source_lesson_id", "source_tool_call_id", "redesign_task_ids", "research_source_ids", "truth_score", "truth_issues", "needs_external_research", "truth_review_status", "latest_review", "review_history", "review_version", "created_at", "updated_at")
values ('draft-bridge-g6-batch1-math-ratios-rate-lab', 'bridge', '6', 'math', 'Ratio Lab: Fair Comparisons', 'Use ratio tables, double number lines, and unit rates to compare real-world deals fairly.', 'Ratios, Rates, And Proportional Reasoning', '["ccss-math-6-rp"]'::jsonb, 'How can a model prove which deal is actually better?', 'This Bridge Academy mission teaches you to use a ratio table and double number line before writing a final answer.', 'This is built like a real middle-school class session: the app teaches, you use a visual model, your team builds evidence, the tutor helps with the stuck point, and mastery depends on explanation plus recall.', '["ratio","equivalent ratio","rate","unit rate","scale factor"]'::jsonb, '["Can write one complete explanation sentence.","Can point to a model or source before answering.","Can revise after feedback."]'::jsonb, '{"warmUp":"The app shows a cyber-neon ratio table and double number line. Write one thing you notice and one question before the rule appears.","directInstruction":"The app teaches ratios, rates, and proportional reasoning in three beats: concrete situation, visual model, then academic language. The student must explain the model before practice unlocks.","guidedPractice":"Work through one example with feedback. The app asks which part of the ratio table and double number line proves each move.","interactiveActivity":"Build or annotate a ratio table and double number line. Drag labels, choose evidence, and write one because sentence that connects the model to the answer.","independentPractice":"Complete two solo checks: one familiar problem and one changed-context transfer problem.","reteachPath":"If the learner misses mastery, the app returns to the ratio table and double number line, hides extra steps, and asks one first-principles question.","challengePath":"If mastery is strong, the learner creates a new example, predicts a mistake, and writes a tutor hint for another student."}'::jsonb, '[{"title":"Model before answer","note":"Do not score the final answer until the learner connects it to the ratio table and double number line."},{"title":"Diagnose the stuck point","note":"Ask whether the learner is stuck on vocabulary, the first step, choosing evidence, or explaining why."},{"title":"Team plus individual proof","note":"The group artifact is shared, but every learner submits one independent evidence sentence."},{"title":"Recall unlock","note":"Reward XP is strongest after the learner can retrieve the idea later, not only during the first attempt."}]'::jsonb, '[{"misunderstanding":"The student picks the lower total price without comparing the price per one unit.","repair":"Divide or scale to one unit, then write a sentence naming the unit rate for each deal.","signal":"The response looks complete but does not explain the model-to-answer connection."},{"misunderstanding":"The student copies a vocabulary word without using it in context.","repair":"Ask for a plain-language definition, a visual pointer, and one example from the task.","signal":"The answer contains the word but no evidence or example."},{"misunderstanding":"The student waits for the tutor to give the answer.","repair":"The tutor asks for the first step, shows one hint, and requires a retry before revealing more.","signal":"The student asks for the final answer or says only ''I don''t know.''"}]'::jsonb, '[{"placement":"lesson-hero","title":"Ratio Lab: Fair Comparisons mission board","description":"A bold Grade 6 class mission board for Ratios, Rates, And Proportional Reasoning.","prompt":"Create a cyber-neon Grade 6 math lesson hero for Ratio Lab: Fair Comparisons. Show ratio table and double number line, student mission, and mastery reward. No real children, no private data, no logos.","altText":"Ratio Lab: Fair Comparisons mission board with ratio table and double number line."},{"placement":"teaching-diagram","title":"ratio table and double number line teaching diagram","description":"A labeled diagram that breaks the lesson model into visible parts and one learner action.","prompt":"Create a readable teaching diagram for Grade 6 math: ratio table and double number line. Include labels, arrows, one example, and learner action. High contrast, classroom safe.","altText":"ratio table and double number line teaching diagram for Ratio Lab: Fair Comparisons."},{"placement":"ai-tutor","title":"Ratio Lab: Fair Comparisons tutor stuck-point card","description":"Tutor card with stuck-point lanes: vocabulary, first step, visual model, evidence, and explanation.","prompt":"Create a tutor help card for Ratio Lab: Fair Comparisons. Show stuck-point lanes and hint-before-answer flow. No real children, no logos.","altText":"Tutor stuck-point card for Ratio Lab: Fair Comparisons."},{"placement":"misconception-repair","title":"Ratio Lab: Fair Comparisons repair board","description":"Divide or scale to one unit, then write a sentence naming the unit rate for each deal.","prompt":"Create a misconception repair board for Ratio Lab: Fair Comparisons. Show wrong idea, model check, repair move, retry. High contrast, short labels.","altText":"Misconception repair board for Ratio Lab: Fair Comparisons."},{"placement":"group-homework","title":"Deal Detective Crew visual","description":"Build a fair-comparison board for two snack, game-currency, or classroom-supply deals.","prompt":"Create a group mission board for Deal Detective Crew. Include roles, shared artifact, individual proof, and review checklist. Cyber-neon academy style.","altText":"Deal Detective Crew group mission visual."}]'::jsonb, '[{"questionText":"What makes an answer strong in Ratio Lab: Fair Comparisons?","questionType":"multiple-choice","choices":["It is short","It uses a model and explains the evidence","It copies a vocabulary word","It skips the first step"],"correctAnswer":"It uses a model and explains the evidence","explanation":"Bridge Academy mastery requires evidence and reasoning, not just a final answer.","difficultyLevel":"core","skillTag":"math-ratios-rates-and-proportional-reasoning","standardTag":"ccss-math-6-rp"},{"questionText":"Which move best repairs this misconception: The student picks the lower total price without comparing the price per one unit.","questionType":"multiple-choice","choices":["Divide or scale to one unit, then write a sentence naming the unit rate for each deal.","Ask for the final answer","Add more unrelated facts","Skip the visual model"],"correctAnswer":"Divide or scale to one unit, then write a sentence naming the unit rate for each deal.","explanation":"The repair targets the actual misunderstanding and returns to the model.","difficultyLevel":"developing","skillTag":"math-ratios-rates-and-proportional-reasoning-misconception","standardTag":"ccss-math-6-rp"},{"questionText":"What should the tutor ask before giving help?","questionType":"multiple-choice","choices":["What exactly feels confusing?","Do you want me to finish it?","Should we skip the model?","Which reward do you want?"],"correctAnswer":"What exactly feels confusing?","explanation":"The tutor has to diagnose the stuck point before choosing an explanation mode.","difficultyLevel":"core","skillTag":"tutor-confusion-diagnosis","standardTag":"ccss-math-6-rp"},{"questionText":"Why does the group task still require individual evidence?","questionType":"multiple-choice","choices":["So one person can do all the work","So each learner proves their own understanding","So the task is longer","So the quiz can be skipped"],"correctAnswer":"So each learner proves their own understanding","explanation":"Collaboration helps learning, but mastery still needs individual proof.","difficultyLevel":"transfer","skillTag":"math-ratios-rates-and-proportional-reasoning-group-accountability","standardTag":"ccss-math-6-rp"}]'::jsonb, '[{"sourceId":"bridge-g6-batch1-math","title":"Bridge Academy Batch 1 Grade 6 Mathematics","url":"","claim":"Ratio Lab: Fair Comparisons is an original Nexus lesson aligned to the documented Grade 6 Batch 1 scope and standards tags.","checkedAt":"2026-07-16T00:00:00.000Z","reviewerNote":"Original lesson design. External IXL references may guide coverage only and must not be copied."},{"sourceId":"grade-6-california-scope-sequence","title":"Bridge Academy Grade 6 California Scope Sequence","url":"docs/curriculum/grade-6-california-scope-sequence.md","claim":"Batch 1 should cover ratios/rates, expressions/equations, weather systems, close reading/evidence, and early-human historical thinking.","checkedAt":"2026-07-16T00:00:00.000Z","reviewerNote":"Local source-of-truth scope sequence for the first sellable Bridge Academy wedge."}]'::jsonb, '{"title":"Deal Detective Crew","roles":["Facilitator","Model builder","Evidence checker","Reporter"],"sharedArtifact":"Build a fair-comparison board for two snack, game-currency, or classroom-supply deals.","individualAccountability":"Each learner explains one part in their own words."}'::jsonb, 'review', '', 'Bridge Academy Batch 1 lesson 1 of 5. Original Nexus content; do not copy proprietary IXL explanations, question banks, or sequence.', 'Every diagram needs alt text, readable labels, keyboard-completable interactions, captions, and a non-color-only explanation path.', 'Grade 6 Bridge Academy pacing: independent but scaffolded, visual first, group artifact with individual accountability, tutor hints before answers.', true, 'ready', '[]'::jsonb, null, '', '[]'::jsonb, '[]'::jsonb, 4, '["Truth-policy and standards review required before publication."]'::jsonb, false, 'needs-human-review', '{}'::jsonb, '[]'::jsonb, 0, '2026-07-10T12:00:00.000Z', '2026-07-10T12:00:00.000Z')
